package com.sarc.backend.web;
import com.sarc.backend.dto.*; import com.sarc.backend.service.*; import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import jakarta.validation.Valid;
@RestController @RequestMapping("/api/usuarios") class UsuarioController { private final UsuarioService s; UsuarioController(UsuarioService x){s=x;} @PostMapping public Object crear(@Valid @RequestBody UsuarioRequest x){return s.crear(x);} @PostMapping("/login") public Object login(@Valid @RequestBody LoginRequest x){return s.login(x);} @GetMapping public Object all(){return s.all();} }
@RestController @RequestMapping("/api/citas") class CitaController {private final CitaService s; CitaController(CitaService x){s=x;} @PostMapping public Object crear(@Valid @RequestBody CitaRequest x){return s.crear(x);}@PutMapping("/{id}/cancelar") public Object cancelar(@PathVariable Long id){return s.cancelar(id);}@GetMapping public Object all(){return s.all();}}
@RestController @RequestMapping("/api/partes-medicos") class ParteController {private final ParteService s; ParteController(ParteService x){s=x;} @PutMapping("/{citaId}") public Object guardar(@PathVariable Long citaId,@Valid @RequestBody ParteRequest x){return s.guardar(citaId,x);}}
